INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Lease note', 'Las fechas de contrato y de hecho se llevan 4 meses. El inicio de pago de renta en contrato es 15 de noviembre del 2023 (vencimiento del plazo de gracia) y realmente se inició a pagar en abril del 2024', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Vigencia', 'Hay un error en el apartado de definiciones respecto a la fecha de terminación del contrato, ya que señala el 14 de julio de 2027, mientras el clausulado señala el 28 de febrero de 2033', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Domicilio del Contrato', E'Boulevard del Niño Poblano N° 2,510, esquina con la Autopista Puebla-Atlixco, Municipio de Puebla, Estado Libre y Soberano de Puebla\nLocal número PH 1PA (PH uno A)', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Fecha de Apertura', '30 de marzo de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Fecha de Firma del Contrato', '27 de marzo de 2023', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Late Fees', '11', '4', 'INTERESES MORATORIOS', E'- If the tenant is late in paying rent, they must pay the landlord late interest.\n- The interest is calculated daily.\n- The rate is twice the 28-day Interbank Equilibrium Interest Rate published by the Bank of Mexico.\n- The rate used is from the business day before the tenant was late.', 'En caso de retraso en el pago de la Renta, la Arrendataria se obliga a pagar a la Arrendadora por concepto de intereses moratorios, por cada día que la Arrendataria permanezca en mora, el equivalente a la cantidad que resulte de multiplicar por 2 (dos) la Tasa de Interés Interbancaria de Equilibrio a plazo de 28 días publicada por el Banco de México en el DOF el día hábil inmediato anterior al de la fecha en que la Arrendataria incurra en mora de la obligación de pago correspondiente conforme al presente Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Common Area Maintenance Charges', '7', '2', 'CONTRAPRESTACIÓN', E'- The tenant must pay an additional rent of $70,549.28 MXN plus applicable VAT each month.\n- This payment is due within the first 10 days of each month.\n- The additional rent must be paid in full, including VAT or any other applicable taxes, starting the day after the grace period ends or from the opening date, whichever comes first.\n- The additional rent is intended to cover all expenses related to the maintenance and functionality of the property.', E'Asimismo, la Arrendataria se obliga a pagar mensualmente, la cantidad de $70,549.28 (SETENTA MIL QUINIENTOS CUARENTA Y NUEVE PESOS 28/100 M.N.)más el IVA que le corresponda dentro de los primeros 10 (diez) días naturales de cada mes correspondiente (en adelante la "Renta Adicional").\n\nEl importe de la Renta Adicional deberá ser pagada conjuntamente en una sola exhibición con el IVA correspondiente o cualquier otro impuesto o contribución que le sustituya, a partir del día siguiente al que venza el Periodo de Gracia, o a partir de la Fecha de Apertura, lo que suceda primero. El concepto Renta Adicional será un ingreso por arrendamiento destinado a cubrir todos los gastos por la conservación y funcionalidad del inmueble.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6d2556a5-3d5a-4289-9030-7754c0924aa4', 'Incremento de Renta', '8', '2', 'CONTRAPRESTACIÓN', E'- The fixed monthly rent and additional rent will increase annually every January, starting January 1, 2025.\n- The increase will be based on a specific adjustment factor and current market rental values.\n- The adjustment factor is calculated by dividing the most recent National Consumer Price Index (INPC) before the rent increase by the INPC at the start of the lease or the last adjustment.\n- Both parties agree on the definition of INPC, which is published by the National Institute of Statistics and Geography or another federal government source.', E'La Renta Mensual Fija y Renta Adicional pactadas en esta Cláusula será incrementada en forma ANUAL, en el mes de enero de cada año, a partir del 01 (primero) de enero del 2025 (dos mil veinticinco) aplicando a dichos conceptos del último mes anterior al ajuste, el factor a que se refiere el párrafo siguiente, así como tomando en consideración los Valores de Mercado aplicables al inmueble en materia de arrendamiento que en su momento rijan y que se encuentren vigentes. \n\nEl factor de ajuste para efectos del párrafo anterior se calculará dividiendo el último INPC publicado en fecha anterior al del mes previo al incremento de la Renta Mensual Fija y Renta Adicional entre el último publicado al mes de inicio del arrendamiento o al mes del último ajuste, según corresponda. Ambas partes están de acuerdo en que el INPC significa Índice Nacional de Precios al Consumidor y el mismo es publicado por el Instituto Nacional de Estadística y Geografía o algún otro medio de publicación del Gobierno Federal, por lo tanto, ambas partes manifiestan conocer tanto el significado como los medios de publicación del referido INPC.');
