INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('f9ade7c1-1510-425f-8df5-a70d2e2a7997', 'Domicilio del Contrato', 'El Molino, Carlos Salinas de Gortari # 801, Locales: LA201, LA202, LA203, LA204, LA205, LA206, LA207, LA208, LAZ09, LA210, LA211, LA212, LA213, LA214, LA215, LA216, R301, T301, R302, T302, R303, T303, R304, T304, R305, T305, GIM300 y área de pasillo común 88.6 m2, Colonia Centro, Apodaca, Nuevo León', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('f9ade7c1-1510-425f-8df5-a70d2e2a7997', 'Fecha de Apertura', '2 de enero de 2020', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9ade7c1-1510-425f-8df5-a70d2e2a7997', 'Incremento de Renta', '5', '5', 'INCREMENTOS A LA RENTA', E'- For the first 5 years, the rent will not change or increase due to inflation or any other reason.\n- The rent will increase by 10% at the start of the 6th year and every 5 years after that.\n- If lease renewal options are exercised, the rent will also increase by 10% at the start of each renewal period.\n- The maintenance fee can only increase by the lesser of the annual change in the National Consumer Price Index or 5%.', E'Durante los primeros cinco (5) años del presente Contrato, la Renta no sufrirǎ variaciones ni incrementos por concepto de inflación ni actualización según el Indice Nacional de Precios al Consumidor o cualquier otro concepto o motivo. Siendo el siguiente aumento al inicio del undécimo y cada cinco (5) años posteriores.\n\nLas Partes acuerdan que la Renta únicamente será incrementada en un diez por ciento (10%) a partir del primer mes del inicio del sexto año y en caso de que se ejerzan las opciones de prórroga, respectivamente al inicio de cada una de estas.\n\nDurante la vigencia del presente Contrato, la Cuota de Mantenimiento únicamente podrá aumentar en la cantidad menor entre la variación anual del Indice Nacional de Precios al Consumidor o el cinco porciento (5%).');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9ade7c1-1510-425f-8df5-a70d2e2a7997', 'Common Area Maintenance Charges', '5', '5 BIS', 'INCREMENTOS A LA CUOTA DE MANTENIMIENTO', E'- Durante el contrato, el aumento de la Cuota de Mantenimiento será el menor entre el cambio anual del Índice Nacional de Precios al Consumidor o el 5%.\n- El arrendatario puede verificar y auditar la administración y los gastos del arrendador relacionados con la Cuota de Mantenimiento.', E'Durante la vigencia del presente Contrato, la Cuota de Mantenimiento únicamente podrá aumentar en la cantidad menor entre la variación anual del Indice Nacional de Precios al Consumidor o el cinco por ciento (5%).\n\nEl arrendatario tiene derecho de exactitud de la información de la Cuota de Mantenimiento, por lo cual, podrá revisar y auditar la addministración y los gastos que realice el Arrendador por concepto de Cuota de Mantenimiento.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9ade7c1-1510-425f-8df5-a70d2e2a7997', 'Common Area Maintenance Charges', '5', '4', 'CUOTA DE MANTENIMIENTO', E'- The tenant must pay the landlord a monthly maintenance fee of $40.00 per square meter, totaling $100,409.20, plus VAT.\n- Payment should be made to a bank account in Mexico specified by the landlord.\n- The maintenance fee covers services like cleaning, gardening, painting, facade maintenance, window cleaning, roof and exterior maintenance, security, cameras, access control systems, lighting in common areas, and necessary adjustments for common areas.\n- It also includes parking, corridors, green areas, and other public access locations.\n- Additionally, it covers common expenses, regular fees, extraordinary contributions, and other monetary or in-kind contributions as per the Shopping Center Regulations.', E'El Arrendatario se obliga a pagar al Arrendador por concepto de cuota de Mantenimiento la cantidad mensual de $40.00 (cuarenta pesos 00/100) por metro cuadrado, equivalentes a $100,409.20 (cien mil cuatrocientos nueve pesos 20/100 Moneda Nacional) más el Impuesto al Valor Agregado, la cual deberá ser depositada en la cuenta bancaria ubicada en México que señale el Arrendador por escrito (la "Cuota de Mantenimiento").\n\nLa Cuota de Mantenimiento incluye los siguientes conceptos de manera enunciativa mas no limitativa: limpieza, servicio de jardinería, pintura y mantenimiento de fachada de la plaza comercial, limpieza de ventanas, mantenimiento de techos y fachadas exteriores, seguridad, cámaras, sistema y personal de seguridad, sistemas de control de acceso a la plaza comercial (en caso de existir), iluminación de las áreas comunes de la plaza comercial, adecuaciones necesarias para las áreas comunes, estacionamiento, pasillos, áreas verdes y demás ubicaciones de acceso al público en general, así como cualquier otra necesaria las operaciones óptimas de la plaza comercial y de sus Sara comunes. También incluye los gastos comunes, cuotas ordinarias, aportaciones extraordinarias y demás aportaciones monetarias o en especie que refiere el Reglamento del Centro Comercial.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9ade7c1-1510-425f-8df5-a70d2e2a7997', 'Late Fees', '4', '3', 'RENTA', E'- Si el inquilino se retrasa en el pago del alquiler, se aplicará un cargo por demora.\n- Este cargo es del 3% mensual, calculado según los días de retraso.\n- El inquilino debe pagar este cargo junto con el alquiler atrasado.', 'En caso de que el Arrendatario se retrase en el pago puntual de la Renta, se cobrara una tasa moratoria del tres por ciento (3%) mensual calculado sobre los días de retraso, misma que deberá ser pagada juntamente con la renta atrasada.');
